WITH lines AS (SELECT id, service, host, log_ts, level, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, v) SELECT *, SUM(status_code) OVER (PARTITION BY host ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_status_code, MIN(status_code) OVER (PARTITION BY host ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_status_code, AVG(status_code) OVER (PARTITION BY host ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_status_code FROM lines WHERE status_code = 440
